(function(){
  var P = AutoJS.players()[0];
  var BRL = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var ME = Java.loadClass('com.merlinkitsune.astral_dice.effect.ModEffects');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('effect clear @a');
  AutoJS.command('clear @a');
  AutoJS.command('effect give @a astral_dice:king_power 600 1');
  var arr = P.getActiveEffects().toArray();
  var out = {};
  var id = 'none', amp = -1, ticks = -1, sameEntry = false;
  var wantKey = String(BRL.MOB_EFFECT.getKey(ME.KING_POWER.get()).toString());
  for (var i = 0; i < arr.length; i++){
    var inst = arr[i];
    var holder = inst.getEffect();
    var k = BRL.MOB_EFFECT.getKey(holder.value());
    var kid = (k === null) ? 'unknown' : String(k.toString());
    if (kid === 'astral_dice:king_power'){
      id = kid; amp = inst.getAmplifier(); ticks = inst.getDuration();
      sameEntry = (String(BRL.MOB_EFFECT.getKey(holder.value()).toString()) === wantKey);
    }
  }
  out.effectCount = arr.length;
  out.effectId = id;
  out.amplifier = amp;
  out.ticks = ticks;
  out.registryKeyMatches = wantKey;
  out.isOurRegistryEntry = sameEntry;
  var stateText = String(AutoJS.state());
  out.stateContainsId = stateText.indexOf('astral_dice:king_power') >= 0;
  out.stateContainsAmplifier = stateText.indexOf('"amplifier":1') >= 0;
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  AutoJS.command('effect clear @a');
  AutoJS.command('clear @a');
  return { effectsAfterClear: P.getActiveEffects().size() };
})()
